#include <iostream>
#include <algorithm>

using namespace std;

int main() {
    long long n;
    cin >> n;

    long long maximum = 0;

    for (long long i = 0; i < n; ++i) {
        long long n1 = n;
        long long n2 = n;

        for (int j = 0; j < 3; ++j) {
            if (n1 == 0 || n2 == 0)
                break;

            if (j % 2 == 0) {
                if (i + 1 <= n1 && i + 1 <= n2)
                    n1 -= i + 1;
                else
                    --n1;
            } else {
                if (i + 1 <= n1 && i + 1 <= n2)
                    n2 -= i + 1;
                else
                    --n2;
            }
        }

        maximum = max(maximum, 2 * n - n1 - n2);
    }

    cout << maximum;
    return 0;
}

